input = "grep 'sub hi zi'  | head -6 | cat > 'output.txt'";
manager.setup(input);
manager.run();

result = "";
i = input.FirstIndexOf(param);
write(i);
if (i == -1)
    result = input;
else
    result = input.SubstringFrom(i);
end if;

self.outputPipe.saveToBuffer(result);

result = "";

length = input.Length();
if (param > length)
    result = input;
else
    result = input.Substring(0, param);
end if;

self.outputPipe.saveToBuffer(result);

create object instance pump of Pump;
pump.buffer = "";
self.pump = pump;
helpPipe = pump;

create list commands of string;
segments = input.Split("|");

for each segment in segments

    head = false;
    delimiter = segment.FirstIndexOf("'");
    if (delimiter == -1)
        delimiter = segment.FirstIndexOf("-");
	head = true;
    end if;

    command = segment.Substring(0, delimiter);
    command = command.Replace(" ", "");

    param = segment.SubstringFrom(delimiter+1);
    if (head == true)
	param = param.Replace(" ", "");
    else
        delimiter2 = param.FirstIndexOf("'");
        param = param.Substring(0, delimiter2);
    end if;

    if (command.Contains(">") == true)
        command = command.Replace(">", "");
    end if;

    item = command + "§" + param;
    add item to commands;
end for;

count = commands.Count();
i = 0;
for each cmd in commands
    parts = cmd.Split("§");

    commandName = parts[0];
    parameter = parts[1];

    if (commandName.Contains("grep") == true)
        create object instance grepFilter of GrepFilter;
        helpPipe.outputFilter = grepFilter;
	helpPipe.outputFilter.param = parameter;

    elif (commandName.Contains("head") == true)
        create object instance headFilter of HeadFilter;
        helpPipe.outputFilter = headFilter;
	helpPipe.outputFilter.param = parameter.ParseInt();

    elif (commandName.Contains("less") == true)
        create object instance lessFilter of LessFilter;
        helpPipe.outputFilter = lessFilter;
	helpPipe.outputFilter.param = parameter;

    elif (commandName.Contains("more") == true)
        create object instance moreFilter of MoreFilter;
        helpPipe.outputFilter = moreFilter;
	helpPipe.outputFilter.param = parameter;

    else
        create object instance catFilter of CatFilter;
        helpPipe.outputFilter = catFilter;
	helpPipe.outputFilter.param = parameter;
    end if;

    filter = helpPipe.outputFilter;

    if (i < count - 1)
        create object instance pipe of Pipe;
        filter.outputPipe = pipe;
        helpPipe = pipe;
    else
        create object instance sink of Sink;
        filter.outputPipe = sink;
        sink.manager = self;
    end if;

    i = i + 1;
end for;
